{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfb;--card:#ffffff;--muted:#6b7280;--accent:#2b6cb0;--accent-2:#2b8c6f}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial}
    body{background:linear-gradient(180deg,var(--bg),#f6f8fa);color:#0f172a;line-height:1.45}
    header{background:linear-gradient(90deg,rgba(43,108,176,0.06),rgba(43,140,111,0.03));border-bottom:1px solid rgba(15,23,42,0.04)}
    .wrap{max-width:1100px;margin:0 auto;padding:28px}
    nav{display:flex;gap:18px;align-items:center}
    nav a{color:var(--muted);text-decoration:none;font-weight:600;font-size:14px}
    nav a.active{color:var(--accent)}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start;padding:28px 0}
    .hero h1{margin:0 0 10px;font-size:28px}
    .hero p.lead{margin:0;color:var(--muted)}
    .card{background:var(--card);padding:18px;border-radius:10px;box-shadow:0 6px 18px rgba(11,20,39,0.04)}
    .cols{display:grid;grid-template-columns:1fr 360px;gap:22px;margin-top:18px}
    .muted{color:var(--muted);font-size:14px}
    .pill{display:inline-block;padding:6px 10px;border-radius:999px;background:rgba(43,108,176,0.08);color:var(--accent);font-weight:700;font-size:13px}
    .small{font-size:13px;color:var(--muted)}
    footer{padding:28px 0;color:var(--muted);font-size:13px}
    .widget{margin-top:12px}
    .btn{display:inline-block;background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700}
    .secondary{background:transparent;border:1px solid rgba(15,23,42,0.06);color:var(--muted)}
    .disclaimer{font-size:13px;color:var(--muted);margin-top:14px}
    .grid-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}
    pre{background:#f7f9fb;padding:12px;border-radius:8px;overflow:auto}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav>
        <a href="index.html">Home</a>
        <a class="active" href="about.html">Practice</a>
        <a href="specialties.html">Focus Areas</a>
        <a href="approach.html">Method</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">FAQs</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero">
      <div>
        <h1>{{BUSINESS_NAME}} — thoughtful clinical practice</h1>
        <p class="lead">I offer short, practical clinical work for people navigating transitions, parenting demands, identity questions, and workplace stress. Sessions are private, grounded in evidence-informed methods, and focused on usable steps.</p>

        <div style="margin-top:14px" class="card">
          <div class="pill">Clinician-led, collaborative</div>
          <h3 style="margin:12px 0 6px">A little about me</h3>
          <p class="small">I am a licensed clinician with years of practice supporting adults and couples. I draw on cognitive-behavioral techniques, emotion-focused strategies, and practical coaching skills. My work emphasizes clear goals, gentle curiosity, and attention to safety and boundaries.</p>
          <p class="small" style="margin-top:8px">Confidentiality is central: your sessions and records are private within agreed limits. I do not provide emergency services—if you are in crisis, call local emergency services or a crisis line immediately.</p>
        </div>

      </div>

      <aside>
        <div class="card">
          <strong>Quick connections</strong>
          <div style="margin-top:10px">
            <div class="small">Phone</div>
            <div style="margin-bottom:8px"><a href="tel:{{PHONE}}">{{PHONE}}</a></div>
            <div class="small">Email</div>
            <div><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </div>
          <div style="margin-top:12px"><a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></div>
        </div>

        <div class="card" style="margin-top:14px">
          <strong>Self-check (non-diagnostic)</strong>
          <p class="small">A short intake tool to help you gather what feels most important to bring to a first visit.</p>
          <div class="widget">
            <div id="about-wizard" data-quiz="true"></div>
            <div style="margin-top:10px"><button class="btn" id="about-wizard-run">Start Self-Check</button></div>
          </div>
        </div>
      </aside>

    </section>

    <section style="margin-top:18px">
      <div class="card">
        <h3>Practice values</h3>
        <p class="small">My offers aim to be clear and practical: shorter series for specific issues, and open slots for ongoing consultation. Below are the principles that guide how I work.</p>
        <ul class="small" style="margin-top:12px">
          <li>Collaborative planning — we build the plan together with your priorities front and center.</li>
          <li>Transparency about limits — not a substitute for crisis care, and I will refer when specialized services are needed.</li>
          <li>Confidential record-keeping and a focus on respect and privacy.</li>
        </ul>
      </div>
    </section>

    <section style="margin-top:18px">
      <div class="card">
        <h3>Bring this to a consultation</h3>
        <p class="small">Use the intake tool to generate a short list of discussion prompts you can share at your first session. It’s meant to orient the conversation, not label or diagnose.</p>
        <div class="small">
          <strong>Sample prompts you might bring:</strong>
          <ul>
            <li>What feels hardest in daily life right now?</li>
            <li>What would you like to see change in three months?</li>
            <li>How do you usually cope when stressed?</li>
          </ul>
        </div>
      </div>
    </section>

  </main>

  <footer class="wrap">
    <div class="card">
      <div class="small">Clinical scope: I provide short-term and longer-term psychotherapy for adults. I do not provide legal or emergency services. Confidentiality applies within ethical and legal limits. If you are in immediate danger or need urgent help, please call emergency services or your local crisis line.</div>
    </div>
  </footer>

  <script>
    // Simple intake wizard used on About page
    (function(){
      const container = document.getElementById('about-wizard');
      const start = document.getElementById('about-wizard-run');
      function buildWizard(){
        container.innerHTML = '';
        const steps = [
          {q:'What brings you here now? (a short phrase)',type:'text'},
          {q:'What would you notice if things were a bit better in 8 weeks?',type:'text'},
          {q:'Which areas feel most affected? (check all)',type:'mult',opts:['Sleep','Work or school','Relationships','Mood','Energy','Concentration']},
          {q:'Anything else you want the clinician to understand before meeting?',type:'text'}
        ];
        let idx=0; const answers=[];
        const box = document.createElement('div'); box.className='card';
        const qEl = document.createElement('div'); qEl.style.marginBottom='8px';
        const inputWrap = document.createElement('div');
        const nav = document.createElement('div'); nav.style.marginTop='10px';
        const prevBtn = document.createElement('button'); prevBtn.textContent='Back'; prevBtn.className='secondary btn'; prevBtn.style.marginRight='8px';
        const nextBtn = document.createElement('button'); nextBtn.textContent='Next'; nextBtn.className='btn';
        nav.appendChild(prevBtn); nav.appendChild(nextBtn);
        box.appendChild(qEl); box.appendChild(inputWrap); box.appendChild(nav);
        container.appendChild(box);

        function render(){
          inputWrap.innerHTML=''; qEl.textContent = (idx+1) + '. ' + steps[idx].q;
          const s = steps[idx];
          if(s.type==='text'){
            const ta = document.createElement('textarea'); ta.style.width='100%'; ta.style.height='80px';
            ta.value = answers[idx]||''; inputWrap.appendChild(ta);
            ta.addEventListener('input',e=>answers[idx]=e.target.value);
          } else if(s.type==='mult'){
            s.opts.forEach((o,i)=>{
              const id = 'opt-'+i;
              const div = document.createElement('div');
              const cb = document.createElement('input'); cb.type='checkbox'; cb.id=id; cb.checked = (answers[idx]||[]).includes(o);
              const label = document.createElement('label'); label.htmlFor=id; label.textContent=' '+o; label.style.marginLeft='6px';
              div.appendChild(cb); div.appendChild(label); inputWrap.appendChild(div);
              cb.addEventListener('change',()=>{
                answers[idx] = Array.from(inputWrap.querySelectorAll('input[type=checkbox]')).filter(c=>c.checked).map(c=>c.parentNode.textContent.trim());
              });
            });
          }
          prevBtn.disabled = idx===0;
          nextBtn.textContent = idx===steps.length-1 ? 'Finish' : 'Next';
        }
        prevBtn.addEventListener('click',()=>{ idx = Math.max(0,idx-1); render(); });
        nextBtn.addEventListener('click',()=>{
          if(idx < steps.length-1){ idx++; render(); } else { showSummary(); }
        });
        function showSummary(){
          container.innerHTML='';
          const out = document.createElement('div'); out.className='card';
          const h = document.createElement('h4'); h.textContent='Prepared prompts to bring to consultation';
          const p = document.createElement('pre'); p.style.whiteSpace='pre-wrap';
          let text = 'Self-check summary:\n';
          steps.forEach((s,i)=>{ text += '\n' + s.q + '\n' + (Array.isArray(answers[i])?answers[i].join(', '):answers[i]||'—') + '\n'; });
          p.textContent = text;
          const copy = document.createElement('button'); copy.className='btn'; copy.textContent='Copy summary';
          copy.addEventListener('click',()=>{
            navigator.clipboard.writeText(text).then(()=>{copy.textContent='Copied'; setTimeout(()=>copy.textContent='Copy summary',1500)});
          });
          out.appendChild(h); out.appendChild(p); out.appendChild(copy);
          container.appendChild(out);
        }
        render();
      }
      start.addEventListener('click', buildWizard);
    })();
  </script>
</body>
</html>"} 
{"path":"specialties.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Focus Areas — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#ffffff;--muted:#4b5563;--accent:#1f5fa8;--card:#fff}
    body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:linear-gradient(180deg,#fff,#f7fbff);margin:0;color:#0b1220}
    .wrap{max-width:1100px;margin:0 auto;padding:26px}
    header{border-bottom:1px solid rgba(11,18,32,0.04);padding-bottom:10px}
    nav{display:flex;gap:16px}
    nav a{color:var(--muted);text-decoration:none;font-weight:700}
    h1{font-size:26px;margin:12px 0}
    .masonry{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));grid-auto-rows:1fr;gap:14px}
    .tile{background:var(--card);padding:14px;border-radius:12px;box-shadow:0 6px 20px rgba(12,20,35,0.04);min-height:120px}
    .tile h4{margin:0 0 6px}
    .muted{color:var(--muted);font-size:14px}
    .aside{margin-top:18px}
    .widget{margin-top:10px}
