    .flex{display:flex;gap:12px;align-items:center}
    .note{font-size:13px;color:var(--muted);margin-top:8px}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <nav>
        <a href="index.html">Start</a>
        <a href="about.html">Practice</a>
        <a class="active" href="specialties.html">Focus Areas</a>
        <a href="approach.html">Method</a>
        <a href="fees.html">Investment</a>
        <a href="faq.html">FAQs</a>
        <a href="book.html">Schedule</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main>
      <h1>Focus areas and typical work</h1>
      <p class="muted">Below are common topics I support. Each card includes what to expect in a short focused series and when a longer plan is often helpful.</p>

      <section class="masonry" aria-label="specialties">
        <article class="tile">
          <h4>Transition and Life Change</h4>
          <p class="muted">Short series: 4–6 sessions to name priorities and set practical steps. Ongoing: monthly check-ins to maintain direction.</p>
        </article>
        <article class="tile">
          <h4>Workplace Stress & Boundaries</h4>
          <p class="muted">Short series: skill-building around communication and decision clarity. Longer work for complex workplace conflicts.</p>
        </article>
        <article class="tile">
          <h4>Parenting & Relationship Patterns</h4>
          <p class="muted">Focused modules address co-parenting strategies, emotion regulation, and small experiments to try between sessions.</p>
        </article>
        <article class="tile">
          <h4>Self-doubt, Perfectionism</h4>
          <p class="muted">Short structure: identify unhelpful routines and try 3 small behavioral shifts between sessions.</p>
        </article>
        <article class="tile">
          <h4>Life re-orientation (career, identity)</h4>
          <p class="muted">A collaborative roadmap for next steps—practical tools to test choices with low risk.</p>
        </article>
      </section>

      <aside class="aside">
        <div class="tile">
          <strong>Session Planner</strong>
          <p class="note">Build a short series personalized for your needs. Export a plain-text plan to copy into a message or bring to a first visit.</p>
          <div id="planner"></div>
        </div>
      </aside>

      <section style="margin-top:16px">
        <div class="tile">
          <strong>When a short series might not be enough</strong>
          <p class="muted">Some situations benefit from longer work or specialized services. If you have complex trauma, active suicidal thoughts, or require emergency care, those are outside the scope of this practice—I'll help connect you with appropriate services.</p>
        </div>
      </section>

    </main>

    <footer style="margin-top:18px">
      <div class="muted">Confidentiality note: information shared in sessions is private within standard ethical and legal limits. This practice does not provide crisis response—if you are in immediate danger please call emergency services or a crisis line in {{CITY}}, {{STATE}}.</div>
    </footer>
  </div>

  <script>
    // Session Planner widget (specialties page)
    (function(){
      const mount = document.getElementById('planner');
      const wrap = document.createElement('div'); wrap.className='card';
      wrap.style.padding='12px';

      wrap.innerHTML = '\n        <label style="display:block;margin-bottom:8px">Primary focus (short phrase)</label>\n        <input id="sp-focus" style="width:100%;padding:8px;margin-bottom:8px" placeholder="eg. Manage work stress">\n        <label style="display:block;margin-bottom:8px">Session length</label>\n        <select id="sp-length" style="width:100%;padding:8px;margin-bottom:8px">\n          <option>50 minutes</option>\n          <option>75 minutes</option>\n          <option>30 minutes</option>\n        </select>\n        <label style="display:block;margin-bottom:8px">Recommended series</label>\n        <select id="sp-series" style="width:100%;padding:8px;margin-bottom:8px">\n          <option value="brief">3-session Brief Series</option>\n          <option value="focused">6-session Focused Series</option>\n          <option value="orientation">Orientation + plan (2 sessions)</option>\n        </select>\n        <label style="display:block;margin-bottom:6px">Top 3 goals (comma separated)</label>\n        <input id="sp-goals" style="width:100%;padding:8px;margin-bottom:10px" placeholder="eg. sleep, assertive communication, routine">\n        <div style="display:flex;gap:8px">\n          <button id="sp-generate" class="btn">Generate plan</button>\n          <button id="sp-copy" class="secondary btn">Copy</button>\n          <button id="sp-download" class="secondary btn">Download .txt</button>\n        </div>\n        <pre id="sp-output" style="margin-top:10px;white-space:pre-wrap;background:#f7fbff;padding:10px;border-radius:8px"></pre>\n      ';

      mount.appendChild(wrap);

      const out = wrap.querySelector('#sp-output');
      wrap.querySelector('#sp-generate').addEventListener('click',()=>{
        const focus = wrap.querySelector('#sp-focus').value.trim() || '—';
        const length = wrap.querySelector('#sp-length').value;
        const series = wrap.querySelector('#sp-series').value;
        const goals = wrap.querySelector('#sp-goals').value || '—';
        let seriesDesc = '';
        if(series==='brief') seriesDesc = '3-session Brief Series: targeted tools and a small plan to try between sessions.';
        if(series==='focused') seriesDesc = '6-session Focused Series: deeper exploration and iterative skill-building.';
        if(series==='orientation') seriesDesc = 'Orientation + plan: an initial session and a follow-up focused on a practical roadmap.';
        const text = `Personal session plan\n\nFocus: ${focus}\nSession length: ${length}\nRecommended format: ${seriesDesc}\nTop goals: ${goals}\n\nSuggested session outline:\n1) Intake & goal setting\n2) Skill practice + experiments\n3) Consolidation and next steps\n\nConfidentiality note: this plan is for planning and discussion purposes. It is not a diagnosis or emergency plan.`;
        out.textContent = text;
      });

      wrap.querySelector('#sp-copy').addEventListener('click',()=>{
        navigator.clipboard.writeText(out.textContent||'').then(()=>{alert('Plan copied to clipboard')});
      });
      wrap.querySelector('#sp-download').addEventListener('click',()=>{
        const blob = new Blob([out.textContent||''],{type:'text/plain'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href=url; a.download='session-plan.txt'; a.click(); URL.revokeObjectURL(url);
      });
    })();
  </script>
</body>
</html>"} 
{"path":"approach.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Method — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f5f8fb;--card:#fff;--accent:#0f6fb8;--muted:#56606b}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;background:var(--bg);color:#071124}
    .wrap{max-width:1050px;margin:0 auto;padding:26px}
    header{padding-bottom:12px}
    nav{display:flex;gap:14px}
    nav a{color:var(--muted);text-decoration:none;font-weight:700}
    h1{margin:6px 0;font-size:26px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:20px}
    .card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 8px 24px rgba(7,17,36,0.04)}
    .muted{color:var(--muted)}
    .pill{background:rgba(15,111,184,0.06);color:var(--accent);padding:6px 10px;border-radius:999px;font-weight:700}
    .section{margin-top:16px}
    .btn{background:var(--accent);color:#fff;border:none;padding:10px 12px;border-radius:8px}
    .secondary{background:transparent;border:1px solid rgba(7,17,36,0.06);padding:9px;border-radius:8px}
    .testimonial{font-style:italic;color:var(--muted);padding-left:8px;border-left:3px solid rgba(15,111,184,0.08)}
    pre{background:#f2f6fb;padding:10px;border-radius:8px}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <nav>
        <a href="index.html">Home</a>
        <a href="about.html">Practice</a>
        <a href="specialties.html">Areas</a>
        <a class="active" href="approach.html">Method</a>
        <a href="fees.html">Fees</a>
        <a href="faq.html">Help</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Contact</a>
      </nav>
    </header>

    <main class="grid">
      <div>
        <div class="card">
          <div class="pill">Practical clinical sequence</div>
          <h1>How I typically work with people</h1>
          <p class="muted">My method is collaborative and time-conscious. Each series begins with clearer goals and ends with an actionable plan. Interventions are chosen to match your current priorities, and we review progress along the way.</p>

          <div class="section">
            <h3>Framework</h3>
            <ol class="muted">
              <li>Clarify: set a shared, practical goal for this work.</li>
              <li>Try: practice one small change between sessions.</li>
              <li>Reflect: review what's helped and adjust the plan.</li>
            </ol>
          </div>

          <div class="section">
            <h3>Clinical boundaries & privacy</h3>
            <p class="muted">Sessions are confidential within ethical and legal limits. I do not provide emergency care; if you are at immediate risk of harm, contact local emergency services or a crisis resource in {{CITY}}, {{STATE}}.</p>
          </div>

          <div class="section">
            <h3>Program options — framed as helpful structures</h3>
            <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:8px">
              <div class="card" style="padding:10px">
                <strong>Orientation</strong>
                <div class="muted">One assessment session + short summary</div>
              </div>
              <div class="card" style="padding:10px">
                <strong>Focused Series</strong>
                <div class="muted">4–6 sessions for a concrete problem</div>
              </div>
              <div class="card" style="padding:10px">
                <strong>Ongoing Consultation</strong>
                <div class="muted">Monthly sessions for maintenance and planning</div>
              </div>
            </div>
          </div>

          <div class="section">
            <h3>Testimonials</h3>
            <div class="testimonial">"Clear goals and usable steps—helped me make choices without feeling lost."</div>
            <div style="height:8px"></div>
            <div class="testimonial">"Practical, calm guidance that respected my boundaries and schedule."</div>
          </div>

        </div>

        <div class="card section" style="margin-top:14px">
          <h3>Self-screening intake (non-diagnostic)</h3>
          <p class="muted">A guided set of questions you can complete now. The tool will produce a list you can copy and bring to your first appointment to make the initial meeting more focused.</p>
          <div id="approach-wizard"></div>
        </div>

      </div>

      <aside>
        <div class="card">
          <h3>Make a plan — Session Planner</h3>
          <p class="muted">Create a short, plain-text session plan to bring to a booking or to keep for yourself.</p>
          <div id="approach-planner"></div>
          <div style="margin-top:12px"><a class="btn" href="book.html">Reserve a time</a></div>
        </div>

        <div class="card" style="margin-top:14px">
          <h4>Scope & crisis note</h4>
          <p class="muted">This practice focuses on outpatient psychotherapy and consultation for adults. If you are experiencing a crisis or are in immediate danger, call emergency services or a crisis hotline in {{CITY}}, {{STATE}}.</p>
        </div>
      </aside>

    </main>
  </div>

  <script>
    // Combined Session Planner and Intake Wizard for Approach page
    (function(){
      // Planner
      const pm = document.getElementById('approach-planner');
      pm.innerHTML = `\n        <label>Presenting concern</label>\n        <input id="p-focus" style="width:100%;padding:8px;margin-bottom:8px" placeholder="eg. Decision fatigue">\n        <label>Recommended structure</label>\n        <select id="p-format" style="width:100%;padding:8px;margin-bottom:8px">\n          <option value="orientation">Orientation (1-2 sessions)</option>\n          <option value="focused">Focused Series (4-6)</option>\n          <option value="ongoing">Ongoing (monthly)</option>\n        </select>\n        <label>Key outcomes (3)</label>\n        <input id="p-goals" style="width:100%;padding:8px;margin-bottom:8px" placeholder="eg. clearer priorities, reduced reactivity">\n        <button id="p-gen" class="btn">Create plan</button>\n        <pre id="p-out" style="margin-top:8px;background:#f5f9ff;padding:10px;border-radius:8px"></pre>\n        <div style="display:flex;gap:8px;margin-top:8px">\n          <button id="p-copy" class="btn">Copy</button>\n          <button id="p-download" class="secondary">Download</button>\n        </div>\n      `;
      const pGen = document.getElementById('p-gen');
      const pOut = document.getElementById('p-out');
      pGen.addEventListener('click',()=>{
        const f = document.getElementById('p-focus').value||'—';
        const fmt = document.getElementById('p-format').value;
        const goals = document.getElementById('p-goals').value || '—';
        const mapping = {orientation:'Orientation: assessment and planning', focused:'Focused Series: targeted practice and review', ongoing:'Ongoing consultation: maintenance and planning'};
        const txt = `Session plan:\n\nFocus: ${f}\nFormat: ${mapping[fmt]}\nGoals: ${goals}\n\nSuggested rhythm:\n- Week 1: assessment and prioritized goal\n- Week 2: skill adoption and feedback\n- Week 3: review and next steps\n\nNotes: This is a planning tool; it does not replace clinical assessment.`;
