      });
      document.getElementById('p-copy').addEventListener('click',()=>{
        navigator.clipboard.writeText(pOut.textContent||'').then(()=>alert('Plan copied'));
      });
      document.getElementById('p-download').addEventListener('click',()=>{
        const blob = new Blob([pOut.textContent||''],{type:'text/plain'});
        const url = URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download='plan.txt'; a.click(); URL.revokeObjectURL(url);
      });

      // Intake Wizard (approach)
      const iw = document.getElementById('approach-wizard');
      function startIntake(){
        iw.innerHTML='';
        const steps = [
          {q:'In one sentence, what would you most like to see change?', type:'text'},
          {q:'How long have you been dealing with this?', type:'text'},
          {q:'What helps you cope in difficult moments? (brief list)', type:'text'},
          {q:'Are there logistical constraints for sessions? (times, location, technology)', type:'text'}
        ];
        let idx=0; const ans=[];
        const box = document.createElement('div'); box.className='card'; box.style.padding='12px';
        const q = document.createElement('div'); const input = document.createElement('textarea'); input.style.width='100%'; input.style.height='70px'; input.style.marginTop='8px';
        const nav = document.createElement('div'); nav.style.marginTop='10px';
        const back = document.createElement('button'); back.textContent='Back'; back.className='secondary'; back.style.marginRight='8px';
