        nav.appendChild(back); nav.appendChild(next);
        box.appendChild(q); box.appendChild(input); box.appendChild(nav);
        iw.appendChild(box);
        function render(){
          q.textContent = (idx+1) + '. ' + steps[idx].q;
          input.value = ans[idx]||'';
          back.disabled = idx===0;
          next.textContent = idx===steps.length-1 ? 'Finish' : 'Next';
        }
        back.addEventListener('click',()=>{ ans[idx]=input.value; idx=Math.max(0,idx-1); input.value = ans[idx]||''; render(); });
        next.addEventListener('click',()=>{ ans[idx]=input.value; if(idx < steps.length-1){ idx++; input.value = ans[idx]||''; render(); } else { finish(); } });
