          steps.forEach((s,i)=>{ txt += s.q + '\n' + (ans[i]||'—') + '\n\n'; });
          txt += 'Suggested prompts to discuss at the appointment:\n- Prioritized goals\n- Recent patterns that matter most\n- What has helped in the past\n';
          pre.textContent = txt;
          const copy = document.createElement('button'); copy.className='btn'; copy.textContent='Copy';
          copy.addEventListener('click',()=>{ navigator.clipboard.writeText(txt).then(()=>copy.textContent='Copied'); setTimeout(()=>copy.textContent='Copy',1200); });
          out.appendChild(h); out.appendChild(pre); out.appendChild(copy);
          iw.appendChild(out);
        }
      }
      // start immediately
      startIntake();
    })();
